using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private readonly ShoppingCart _cart;

    public ShoppingCartTests()
    {
        _cart = new ShoppingCart();
    }

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-1", 2, 9.99m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual(2, _cart.Items["SKU-1"].Quantity);
        Assert.AreEqual(9.99m, _cart.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-1", 1, 5.00m);
        _cart.AddItem("SKU-1", 3, 5.00m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual(4, _cart.Items["SKU-1"].Quantity);
    }

    [TestMethod]
    public void AddItem_DifferentSkus_AddsMultipleEntries()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 2, 20m);

        Assert.HasCount(2, _cart.Items);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_NullOrEmptySku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_Throws(int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-1", quantity, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-1", 1, -1m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _cart.AddItem("FREE", 1, 0m);

        Assert.AreEqual(0m, _cart.Items["FREE"].Price);
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-1", 1, 10m);

        _cart.RemoveItem("SKU-1");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsExactly<KeyNotFoundException>(
            () => _cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void RemoveItem_NullOrEmptySku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    [TestMethod]
    public void RemoveItem_OnlyRemovesTargetSku()
    {
        _cart.AddItem("A", 1, 5m);
        _cart.AddItem("B", 1, 10m);

        _cart.RemoveItem("A");

        Assert.HasCount(1, _cart.Items);
        Assert.Contains("B", _cart.Items.Keys);
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
    {
        _cart.AddItem("SKU-1", 3, 10m);

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    [TestMethod]
    [DynamicData(nameof(MultiItemTestData))]
    public void CalculateTotal_MultipleItems_SumsCorrectly(
        (string Sku, int Qty, decimal Price)[] items, decimal expectedTotal)
    {
        foreach (var (sku, qty, price) in items)
            _cart.AddItem(sku, qty, price);

        Assert.AreEqual(expectedTotal, _cart.CalculateTotal());
    }

    public static IEnumerable<((string, int, decimal)[] Items, decimal Expected)> MultiItemTestData =>
    [
        (new[] { ("A", 1, 10m), ("B", 2, 5m) }, 20m),
        (new[] { ("A", 1, 0m), ("B", 1, 0m) }, 0m),
        (new[] { ("X", 10, 1.50m) }, 15m),
    ];

    [TestMethod]
    public void CalculateTotal_AfterRemove_ExcludesRemovedItem()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 1, 20m);
        _cart.RemoveItem("A");

        Assert.AreEqual(20m, _cart.CalculateTotal());
    }

    // ── ApplyCoupon ──────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 10)]
    [DataRow("SAVE20", 20)]
    [DataRow("HALF", 50)]
    public void ApplyCoupon_ValidCode_AppliesDiscount(string code, int discountPercent)
    {
        _cart.AddItem("SKU-1", 1, 100m);
        _cart.ApplyCoupon(code);

        var expected = 100m - (100m * discountPercent / 100m);
        Assert.AreEqual(expected, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_AppliesDiscount()
    {
        _cart.AddItem("SKU-1", 1, 100m);
        _cart.ApplyCoupon("save10");

        Assert.AreEqual(90m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _cart.ApplyCoupon("BOGUS"));

        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ApplyCoupon_NullOrEmptyCode_Throws(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedByNewCoupon_UsesLatestDiscount()
    {
        _cart.AddItem("SKU-1", 1, 100m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_EmptyCart_TotalRemainsZero()
    {
        _cart.ApplyCoupon("HALF");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }
}

